<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use App\Modules\Tourism\Services\TourismProviderService;use RuntimeException;use Throwable;
final class TourismProviderController extends Controller{private TourismProviderService $s;private Authorization $a;public function __construct(){$this->s=new TourismProviderService();$this->a=new Authorization();}private function allow(string $p,string $r='/tourism'):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}public function index():void{if(!$this->allow('tourism.providers.view'))return;$t=(int)Auth::tenantId();$trash=($_GET['view']??'')==='trash';$this->view('Tourism::Providers.index',['title'=>$trash?'Deleted Tourism Providers':'Tourism Providers','providers'=>$this->s->all($t,$trash),'trash'=>$trash]);}public function create():void{if(!$this->allow('tourism.providers.create','/tourism/providers'))return;$this->view('Tourism::Providers.create',['title'=>'Add Tourism Provider','locations'=>$this->s->locations()]);}public function store():void{if(!$this->allow('tourism.providers.create','/tourism/providers'))return;$t=(int)Auth::tenantId();try{$id=$this->s->create($t,$_POST,(int)Auth::id());flash('success','Tourism provider created successfully.');redirect('/tourism/providers/'.$id);}catch(Throwable $e){$this->view('Tourism::Providers.create',['title'=>'Add Tourism Provider','locations'=>$this->s->locations(),'error'=>$e->getMessage(),'old'=>$_POST]);}}public function show(int $id):void{if(!$this->allow('tourism.providers.view','/tourism/providers'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('Tourism::Providers.show',['title'=>$r['business_name'],'record'=>$r]);}public function edit(int $id):void{if(!$this->allow('tourism.providers.edit','/tourism/providers'))return;$r=$this->s->find((int)Auth::tenantId(),$id);if(!$r)abort(404);$this->view('Tourism::Providers.edit',['title'=>'Edit Tourism Provider','record'=>$r,'locations'=>$this->s->locations()]);}public function update(int $id):void{if(!$this->allow('tourism.providers.edit','/tourism/providers'))return;$t=(int)Auth::tenantId();try{$this->s->update($t,$id,$_POST,(int)Auth::id());flash('success','Tourism provider updated successfully.');redirect('/tourism/providers/'.$id);}catch(Throwable $e){$r=$this->s->find($t,$id)??$_POST;$this->view('Tourism::Providers.edit',['title'=>'Edit Tourism Provider','record'=>$r,'locations'=>$this->s->locations(),'error'=>$e->getMessage()]);}}public function destroy(int $id):void{if(!$this->allow('tourism.providers.delete','/tourism/providers'))return;try{$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Tourism provider moved to Trash.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/providers');}public function restore(int $id):void{if(!$this->allow('tourism.providers.delete','/tourism/providers?view=trash'))return;try{$this->s->restore((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Tourism provider restored.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/providers?view=trash');}}
